'use strict';
// Sources reviewed on 2026-10-14. Guidance is educational, not a live warning feed.
const V26SOURCES={reviewed:'2026-10-14',warning:'https://weather.sz.gov.cn/qixiangfuwu/yujingfuwu/tufashijianyujing/index.html',guide:'https://weather.sz.gov.cn/qixiangfuwu/yujingfuwu/fangyuzhiyin/index.html',rain:'https://www.szlh.gov.cn/zmhd/wdzsk/content/post_12722512.html',weather:'https://open-meteo.com/en/docs',humidity:'https://weather.sz.gov.cn/qixiangfuwu/qixiangjiance/shidujiance/index.html',gust:'https://weather.sz.gov.cn/qixiangfuwu/qixiangjiance/zhenfengjiance/index.html'};
function v26ValidateWeather(input){if(!input||!input.current||!Array.isArray(input.hourly?.time)||input.hourly.time.length>400||input.hourly.time.some(t=>typeof t!=='string'||!/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(t)))throw Error('Weather structure unavailable');const w=v20Copy(input);if(w.daily&&(!Array.isArray(w.daily.time)||w.daily.time.length>16||w.daily.time.some(t=>typeof t!=='string'||!/^\d{4}-\d\d-\d\d$/.test(t))))delete w.daily;const expected={temperature_2m:'°C',apparent_temperature:'°C',relative_humidity_2m:'%',cloud_cover:'%',wind_speed_10m:'m/s',wind_gusts_10m:'m/s',wind_direction_10m:'°',surface_pressure:'hPa',precipitation:'mm',precipitation_probability:'%',temperature_2m_min:'°C',temperature_2m_max:'°C',precipitation_sum:'mm',precipitation_probability_max:'%'};
 const valid=(k,v)=>{if(v25Num(v)===null)return null;if(/humidity|cloud_cover|probability/.test(k)&&(v<0||v>100))return null;if(k==='wind_direction_10m'&&(v<0||v>360))return null;if(/precipitation|wind_speed|wind_gusts/.test(k)&&v<0)return null;if(k==='surface_pressure'&&v<=0)return null;return v};
 for(const scope of ['current','hourly','daily']){const obj=w[scope];if(!obj)continue;const units=w[scope+'_units']||{};for(const k of Object.keys(expected)){if(!(k in obj))continue;const mismatch=units[k]!=null&&units[k]!==expected[k];if(scope==='current')obj[k]=mismatch?null:valid(k,obj[k]);else{if(!Array.isArray(obj[k])){obj[k]=Array(obj.time?.length||0).fill(null);continue}obj[k]=obj.time.map((_,i)=>mismatch?null:valid(k,obj[k][i]))}}}return w}
function v26WeatherGuide(){vDialog(v20Text('天气数据怎样读','Reading weather data'),`<div class="v25info"><p>${v20Text('当前数值来自模型网格，不能当作道路或医院入口的实测。数据时刻、获取时刻和计划出发时刻分别显示。','Values come from model grids, not measurements at a road or hospital entrance. Data, retrieval and departure times are distinct.')}</p><div class="tablewrap"><table><tr><th>${v20Text('参数','Variable')}</th><th>${v20Text('含义与边界','Meaning and limits')}</th></tr>${[
 ['湿度（%）','Humidity (%)','2米高度相对湿度，不能推算积水概率。','Relative humidity at 2 m; not flooding probability.'],
 ['体感温度（°C）','Feels-like (°C)','综合温度、风、湿度和辐射的模型指标。','A model measure combining temperature, wind, humidity and radiation.'],
 ['风速 / 阵风（m/s）','Wind / gusts (m/s)','10米高度模型风；逐小时阵风是前一小时最大值。不能由它自动判断台风预警等级。','Model wind at 10 m; hourly gusts are a preceding-hour maximum. They do not establish a typhoon warning.'],
 ['降水量（mm）','Precipitation (mm)','当前降水按接口返回的累计窗口；小时雨量累计前一小时；日雨量累计当天。','Current rain uses the API interval; hourly rain totals the preceding hour, and daily rain totals the day.'],
 ['降水概率（%）','Rain probability (%)','日卡显示小时概率最大值，与三小时≥50mm的集合比例分开。','Daily cards show the maximum hourly probability, separate from ensemble share for ≥50 mm in three hours.'],
 ['气压（hPa）','Pressure (hPa)','显示地面气压，不与海平面气压混用。','Surface pressure, distinct from sea-level pressure.']
 ].map(([zh,en,a,b])=>`<tr><td>${v20Text(zh,en)}</td><td>${v20Text(a,b)}</td></tr>`).join('')}</table></div><p>${v20Text('今天的图可能包含已过去时段的模型值；它们不构成历史现场观测。部分地区的15分钟数据来自小时模型插值。缺测和单位不符的数值显示“—”。','Today’s plots may include elapsed model hours, not historical field observations. Some 15-minute data are interpolated from hourly output. Missing or unit-inconsistent values appear as “—”.')}</p><div class="v25links"><a href="${V26SOURCES.weather}" target="_blank" rel="noopener">${v20Text('接口定义','API definitions')} ↗</a><a href="${V26SOURCES.humidity}" target="_blank" rel="noopener">${v20Text('官方湿度监测','Official humidity observations')} ↗</a><a href="${V26SOURCES.gust}" target="_blank" rel="noopener">${v20Text('官方阵风监测','Official gust observations')} ↗</a></div></div>`)}
function v26TyphoonGuide(){const rows=[
 ['白色','White','注意台风动态，提前准备。','Follow updates and prepare early.','#f0f3f5'],
 ['蓝色','Blue','整理室外易被吹落的物品，留意沿海和户外安排。','Secure outdoor items and review coastal and outdoor plans.','#e4efff'],
 ['黄色','Yellow','关注避险与停课安排，在安全场所暂避。','Check shelter and school notices; stay in a safe place.','#fff7ce'],
 ['橙色','Orange','减少暴露，关注交通调整，留在安全场所。','Reduce exposure, check transport changes and remain sheltered.','#fff0db'],
 ['红色','Red','遵从管制和避险安排；风暂时减弱仍保持戒备。','Follow restrictions and shelter instructions; a temporary lull does not end the danger.','#ffe8e8']
 ];return `<details class="v26guide"><summary>${v20Text('深圳台风预警与出行提示','Shenzhen typhoon warnings and travel guidance')}</summary><p>${v20Text('以下是官方信号的科普对应，不表示当前发布了任何等级；当前官方预警状态未自动取得。模型风速与官方信号分别使用。','This is an educational guide, not the current warning status. Official warnings have not been fetched automatically; model winds and official signals remain distinct.')}</p><div class="v26signals">${rows.map(([zh,en,a,b,col])=>`<div style="background:${col}"><b>${v20Text(zh,en)}</b><span>${v20Text(a,b)}</span></div>`).join('')}</div><p class="muted">${v20Text('概括自深圳市气象局防御说明；具体措施、适用区域和生效时间以官方原文与当次发布为准。','Summarized from Shenzhen meteorological guidance. Consult official text and the issued notice for measures, area and effective time.')}</p><a href="${V26SOURCES.guide}" target="_blank" rel="noopener">${v20Text('查看完整官方含义与措施','Read full official meanings and measures')} ↗</a></details>`}
const v26DisastersBase=v25Disasters;
v25Disasters=function(){v26DisastersBase();const d=document.getElementById('source-dialog');if(d&&typeof d.insertAdjacentHTML==='function')d.insertAdjacentHTML('beforeend',`<div class="v25info"><div class="notice">${v20Text('当前官方预警状态：未接入。缺少资料不表示没有预警。','Current official warning status: not integrated. Missing data does not mean no warning exists.')}</div><a href="${V26SOURCES.warning}" target="_blank" rel="noopener">${v20Text('打开深圳官方预警','Open Shenzhen official warnings')} ↗</a>${v26TyphoonGuide()}<details class="v26guide"><summary>${v20Text('暴雨阈值与模型比例的区别','Rain thresholds and ensemble share')}</summary><p>${v20Text('罗湖区水务局2026年说明中，橙色和红色分别涉及过去三小时雨量达到50和100毫米，并且降雨持续。本站计算的是代表点未来三小时达到降水阈值的模型成员比例，统计时间与发布判断不同，不自动生成官方预警。','Luohu’s 2026 guidance describes orange and red thresholds using past three-hour totals of 50 and 100 mm with continuing rain. Here, the share of ensemble members exceeding a future three-hour threshold is computed; the time window and issuance decision differ. No official warning is generated.')}</p><a href="${V26SOURCES.rain}" target="_blank" rel="noopener">${v20Text('罗湖区水务局说明 · 2026-04-03','Luohu water authority explanation · 2026-04-03')} ↗</a></details><small>${v20Text('资料核查日期','Sources checked')}: ${V26SOURCES.reviewed}</small></div>`)};
const v26SummaryBase=v25WeatherSummary;
v25WeatherSummary=function(w){return v26SummaryBase(w)+`<div class="v26weatherlinks"><button type="button" data-v26="weather-guide">${v20Text('读懂湿度、阵风与降水','Understand humidity, gusts and rain')}</button><a href="${V26SOURCES.warning}" target="_blank" rel="noopener">${v20Text('官方预警 ↗','Official warnings ↗')}</a><small>${v20Text('获取时刻','Retrieved')}: ${w.fetchedAt?esc(dateText(w.fetchedAt)):'—'}</small></div>`};
const v26RainBase=v18RainPanel;
v18RainPanel=function(p){let h=v26RainBase(p);h=h.replace('50mm/3小时和100mm/3小时参考深圳暴雨橙色与红色预警的降水条件；模型概率不会自动发布官方预警。','50与100mm为降水阈值参考；官方说明涉及过去3小时降雨与持续条件，本站是未来3小时模型比例，不能等同于官方预警。').replace('The rainfall thresholds reference Shenzhen warning criteria; the model does not issue official warnings.','Rain thresholds are reference values. Official guidance uses past rainfall and continuing-rain conditions; this future ensemble estimate does not issue warnings.');return h.replace('</details>',`<p><a href="${V26SOURCES.rain}" target="_blank" rel="noopener">${v20Text('罗湖2026年预警含义说明','Luohu 2026 warning explanation')} ↗</a></p></details>`)};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v26]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.v26==='weather-guide')v26WeatherGuide()},true);
